'use strict';
const icons={arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4m2-17a3 3 0 0 1 0 6m1 4a5 5 0 0 1 3 4v3"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zm6-2v16m6-14v16"/>'};
const icon=name=>`<svg class="icon icon-${name}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;
const main=document.getElementById('main');
function welcome(){return `<div class="page landing-page"><div class="welcome-intro landing-panel"><div class="welcome-copy"><div class="eyebrow">Your new-neighbour field guide · Melbourne</div><h1>High floor.<br><span>Real flood risk.</span></h1><p class="landing-overview">A short, interactive welcome to flood safety in Southbank, Melbourne. Explore local maps, pack your essentials and make a plan, then book a relaxed building walk to meet your neighbours.</p><a class="primary landing-start" href="#paths">Get started ${icon('arrow')}</a></div>${welcomePhoto()}</div></div>`}
function pathsPage(){return `<div class="page paths-page"><a class="back-link" href="#welcome">← Back to the module</a><div class="eyebrow">A plan that fits you</div><h1>First, choose your path.</h1><p class="page-intro">Both paths end with a friendly building walk.</p>${hasResponses('resident')||hasResponses('access')?`<div class="resume-line">${icon('check')} Continue from where you left off, or choose “Start again” for a fresh go.</div>`:''}${sharingPanel()}<div class="path-grid">${pathCard('resident')}${pathCard('access')}</div><div class="journey-strip"><div class="journey-item"><span class="journey-number">1</span><div><strong>A little local know-how</strong><p>Maps, mini scenarios, and practical tips.</p></div></div><div class="journey-item"><span class="journey-number">2</span><div><strong>A plan that’s yours</strong><p>Your essentials, your people, your next steps.</p></div></div><div class="journey-item"><span class="journey-number">3</span><div><strong>Meet your neighbours</strong><p>Book a relaxed walk around your building.</p></div></div></div></div>`}
Object.assign(icons,{
 check:'<path d="m5 12 4 4L19 6"/>',medical:'<rect x="3" y="3" width="18" height="18" rx="4"/><path d="M12 7v10m-5-5h10"/>',cup:'<path d="M6 3h12l-1 18H7zM7 9h10"/>',torch:'<path d="M5 3h14l-4 7v11H9V10zM9 10h6"/>',radio:'<rect x="3" y="8" width="18" height="13" rx="3"/><path d="m5 8 13-6M15 12h3m-3 4h3"/><circle cx="8" cy="15" r="2"/>',document:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M9 12h6m-6 4h6"/>',battery:'<rect x="2" y="6" width="18" height="12" rx="2"/><path d="M22 10v4M6 10v4m4-4v4m4-4v4"/>',bag:'<rect x="4" y="7" width="16" height="14" rx="3"/><path d="M8 7V3h8v4m-8 6h8m-8 4h8"/>',spark:'<path d="m12 2 2 7 7 3-7 2-2 8-2-8-8-2 8-3z"/>',flame:'<path d="M12 2c1 6 8 8 8 13a8 8 0 0 1-16 0c0-4 4-7 5-10 0 4 3 5 3 5z"/>',route:'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M7 5h10a4 4 0 0 1 0 8H7a3 3 0 0 0 0 6h10"/>',chat:'<path d="M3 3h18v14H9l-6 4zM7 8h10M7 12h6"/>',heart:'<path d="M12 21 3 12C-2 3 8-1 12 6c4-7 14-3 9 6z"/>',building:'<path d="M5 21V3h14v18M9 7h1m4 0h1m-6 4h1m4 0h1M10 21v-5h4v5M2 21h20"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 11 3 3 5-6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0z"/><circle cx="12" cy="10" r="2"/>'
});
const STORE='southbank-ready-v1';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isObject=x=>x&&typeof x==='object'&&!Array.isArray(x);
let storageAvailable=true;
function readStore(key){try{const data=JSON.parse(localStorage.getItem(key)||'{}');return isObject(data)?data:{}}catch{storageAvailable=false;return {}}}
const saved=readStore(STORE);
let state={lastPath:['resident','access'].includes(saved.lastPath)?saved.lastPath:'resident',completed:{resident:[],access:[]},answers:isObject(saved.answers)?saved.answers:{},packed:isObject(saved.packed)?saved.packed:{},needs:Array.isArray(saved.needs)?saved.needs:[],ack:isObject(saved.ack)?saved.ack:{},plan:isObject(saved.plan)?saved.plan:{},savePlan:saved.savePlan===true,large:saved.large===true,contrast:saved.contrast===true,booking:isObject(saved.booking)?saved.booking:null};
if(state.booking&&(!['resident','access'].includes(state.booking.path)||!/^practice-\d+$/.test(state.booking.id)||!/^\d{4}-\d{2}-\d{2}$/.test(state.booking.date)||!/^\d{2}:\d{2}$/.test(state.booking.time)||!['supported','social'].includes(state.booking.format)))state.booking=null;
for(const path of ['resident','access']){state.completed[path]=Array.isArray(saved.completed?.[path])?saved.completed[path].filter(n=>Number.isInteger(n)&&n>=0&&n<CHAPTERS[path].length):[];state.packed[path]=Array.isArray(state.packed[path])?state.packed[path].filter(id=>KIT_ITEMS.some(x=>x.id===id)):[]}
const CONFIG_KEYS=['buildingName','address','managerName','managerPhone','meetingPoint','accessibleExit','evacuationPlan','infrastructure','bookingUrl','accessibleBookingUrl','verifiedOn'];
function validUrl(url){try{return new URL(url).protocol==='https:'}catch{return false}}
function cleanConfig(input){const out={};for(const key of CONFIG_KEYS){out[key]=typeof input?.[key]==='string'?input[key].trim().slice(0,2500):''}for(const key of ['bookingUrl','accessibleBookingUrl']){if(out[key]&&!validUrl(out[key]))out[key]=''}return out}
let config=cleanConfig({...window.SOUTHBANK_CONFIG,...readStore('southbank-building')});
let current={view:'welcome',path:state.lastPath,index:0};
let mapTab='flood',floorTab='home',powerTab='lift';
let bagMessage={};
let bookingSelection='',bookingFormat='';
function save(){try{localStorage.setItem(STORE,JSON.stringify({...state,plan:state.savePlan?state.plan:{}}))}catch{storageAvailable=false}}
function announce(message){document.getElementById('announcer').textContent=I18N.t(message)}
const provided=value=>`<span translate="no" dir="auto">${esc(value)}</span>`;
function preferences(){document.documentElement.classList.toggle('large-type',state.large);document.body.classList.toggle('high-contrast',state.contrast)}
function sourceLink(id,label){const s=SOURCES.find(x=>x.id===id);return `<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(label||s.name)} ↗</a>`}
function refs(ids){return `<div class="source-note">Read more: ${ids.map(id=>sourceLink(id)).join(' · ')}</div>`}
function notice(text,kind=''){return `<div class="notice ${kind}">${text}</div>`}
function list(items){return `<ul class="useful-list">${items.map(t=>`<li>${t}</li>`).join('')}</ul>`}
function resumeIndex(path){return CHAPTERS[path].findIndex((_,i)=>!state.completed[path].includes(i))}
function complete(path){return resumeIndex(path)===-1}
function readyToBook(path){return complete(path)&&Learning.rounds(path).length>0}
function route(path,index=resumeIndex(path)){return index===-1?(readyToBook(path)?`#complete/${path}`:`#review/${path}`):`#learn/${path}/${index}`}
function progress(path){return Math.round(state.completed[path].length/CHAPTERS[path].length*100)}
function hasResponses(path){return state.completed[path].length>0||state.packed[path].length>0||Object.keys(state.answers).some(key=>key.startsWith(path+':'))||Object.keys(state.ack).some(key=>key.startsWith(path+':'))||(path==='access'&&state.needs.length>0)}
function pathCard(path){const supported=path==='access',started=hasResponses(path);return `<div class="path-option"><a class="path-card ${supported?'path-access':'path-resident'}" href="${route(path)}"><div class="path-top"><span class="icon-box">${icon(supported?'people':'home')}</span><span class="path-meta">${supported?'6 short chapters · about 15 min':'5 short chapters · about 10 min'}</span></div><h2>${supported?'I’m a carer or a person with disability':'I’m a resident or renter'}</h2><p>${supported?'For people with disability and their carers. Explore access, power, communication, and the support that works for you.':'New keys, new neighbourhood. Get to know the local risk, pack the essentials, and make a plan that fits apartment life.'}</p><span class="card-link">${complete(path)?'View learning summary':started?'Continue this path':supported?'Explore this path':'Let’s get started'} <span class="arrow-circle">${icon('arrow')}</span></span></a>${started?`<div class="path-replay"><span>${state.completed[path].length} of ${CHAPTERS[path].length} chapters complete</span><button class="restart-link" data-action="restart-path" data-path="${path}" aria-label="Start ${supported?'supported':'resident and renter'} path again">Start again ↻</button></div>`:''}</div>`}
function replayPanel(path){return `<div class="replay-panel"><div><strong>Fancy another go?</strong><p>Start this path with fresh activity answers. Your personal plan notes stay available.</p></div><button class="secondary" data-action="restart-path" data-path="${path}">Do this path again ↻</button></div>`}
function restartPath(path){
 if(!['resident','access'].includes(path))throw new Error('Choose a valid learning path.');
 Learning.newRun(path);state.completed[path]=[];state.packed[path]=[];
 for(const group of ['answers','ack'])for(const key of Object.keys(state[group]))if(key.startsWith(path+':'))delete state[group][key];
 if(path==='access')state.needs=[];
 if(state.booking?.path===path)state.booking=null;
 bookingSelection='';bookingFormat='';state.lastPath=path;save();
 location.hash=`#learn/${path}/0`;render();announce('Fresh start. This path’s answers and progress have been reset. Your personal plan notes are still available.');
}
function headerActive(view){document.querySelectorAll('.site-header nav a').forEach(a=>{const yes=view==='map'?a.hash==='#map':view==='plan'?a.hash==='#plan':a.hash==='#welcome';if(yes)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')})}
function render(focus=true){
 const parts=(location.hash||'#welcome').slice(1).split('/');
 if(parts[0]==='main'){parts[0]='welcome'}
 const path=['resident','access'].includes(parts[1])?parts[1]:state.lastPath;
 current={view:parts[0],path,index:0};
 let html='';
 if(parts[0]==='learn'&&/^\d+$/.test(parts[2]||'')&&Number(parts[2])<CHAPTERS[path].length){current.index=Number(parts[2]);state.lastPath=path;save();html=lessonPage(path,current.index)}
 else if(parts[0]==='paths')html=pathsPage();
 else if(parts[0]==='map')html=mapPage();
 else if(parts[0]==='plan')html=standalonePlan();
 else if(parts[0]==='sources')html=sourcesPage();
 else if(parts[0]==='poster')html=posterPage();
 else if(parts[0]==='organiser')html=organiserPage();
 else if(parts[0]==='review'&&complete(path))html=reviewPage(path);
 else if(parts[0]==='complete'&&complete(path)&&!readyToBook(path))html=reviewPage(path);
 else if(parts[0]==='complete'&&complete(path))html=completionPage(path).replace('<a class="back-link" href="#paths">← Explore the other path</a>',replayPanel(path)+'<a class="back-link" href="#paths">← Explore the other path</a>');
 else if(parts[0]==='book')html=readyToBook(path)?bookingPage(path):lockedBooking(path);
 else{current.view='welcome';html=welcome()}
 main.innerHTML=html;headerActive(current.view);preferences();
 if(!storageAvailable)main.insertAdjacentHTML('afterbegin','<div class="storage-note" role="status">Browser storage is unavailable. You can still use the module and download your plan, but progress may not be saved.</div>');
 document.documentElement.dataset.pageTitle=(current.view==='learn'?CHAPTERS[path][current.index].label:({poster:'My flood plan',review:'Final check',organiser:'Anonymous learning results.',paths:'Choose your path',map:'Local maps',plan:'My plan',book:'Book your building walk',complete:'Learning complete',sources:'Sources & guidance'}[current.view]||'Your new-neighbour field guide'));
 document.title=I18N.t(document.documentElement.dataset.pageTitle)+' — Southbank Ready';I18N.apply();
 if(focus){window.scrollTo({top:0,behavior:'instant'});main.focus({preventScroll:true})}
}
function lessonPage(path,index){
 const chapters=CHAPTERS[path],c=chapters[index];
 return `<div class="page lesson-layout"><aside class="learning-sidebar"><a class="back-link" href="#paths">← All learning paths</a><div class="sidebar-path">${icon(path==='access'?'people':'home')}<span>${path==='access'?'Your supported plan':'Resident & renter path'}</span></div><div class="progress-label"><span>Your progress</span><strong>${state.completed[path].length} / ${chapters.length}</strong></div><progress value="${state.completed[path].length}" max="${chapters.length}" aria-label="Chapters completed"></progress><ol class="chapter-list">${chapters.map((ch,i)=>`<li><a href="#learn/${path}/${i}" ${i===index?'aria-current="step"':''}><span class="step-number ${state.completed[path].includes(i)?'done':''}">${state.completed[path].includes(i)?icon('check'):String(i+1).padStart(2,'0')}</span><span>${ch.label}</span></a></li>`).join('')}</ol><div class="sidebar-tip">${icon('chat')}<strong>At your pace.</strong><p>Take a break whenever you need. Your chapter progress stays on this device.</p></div><button class="text-button" data-action="help">Useful contacts & emergency help ↗</button></aside><article class="lesson-content"><div class="lesson-kicker"><span>CHAPTER ${String(index+1).padStart(2,'0')}</span><span>${icon('clock')} About ${c.type==='plan'?'3':'2'} min</span></div><h1>${c.title}</h1><p class="lesson-intro">${c.intro}</p><div class="lesson-body">${chapterBody(c,path)}</div>${c.quiz?`<section class="quiz" aria-label="Quick scenario"><div id="quiz-content">${quizHtml(c,path)}</div></section>`:''}<div class="lesson-bottom"><a class="secondary" href="${index===0?'#paths':`#learn/${path}/${index-1}`}">← Back</a><span id="continue-hint">${ready(c,path)?'Ready when you are.':c.type==='kit'?'Check your bag to continue.':c.type==='plan'?'Tick the two reminders to continue.':'Choose the safer answer to continue.'}</span><button class="primary" id="continue" data-action="continue" ${ready(c,path)?'':'disabled'}>${index===chapters.length-1?'Finish this path':'Next chapter'} ${icon('arrow')}</button></div></article></div>`;
}
function ready(c,path){if(c.quiz)return state.answers[path+':'+c.id]===c.quiz.correct;if(c.type==='kit')return bagReady(path)&&Learning.events(path).some(e=>e.question==='kit'&&e.stage==='practice'&&Curriculum.correct(Curriculum.questions(path).find(q=>q.id==='kit'),e.selected));if(c.type==='plan')return state.ack[path+':warning']===true&&state.ack[path+':plan']===true;return true}
function updateContinue(){const c=CHAPTERS[current.path][current.index],button=document.getElementById('continue');if(button){button.disabled=!ready(c,current.path);document.getElementById('continue-hint').textContent=ready(c,current.path)?'Ready when you are.':c.type==='kit'?'Check your bag to continue.':c.type==='plan'?'Tick the two reminders to continue.':'Choose the safer answer to continue.'}}
function quizHtml(c,path){const selected=state.answers[path+':'+c.id],has=Number.isInteger(selected),correct=selected===c.quiz.correct;return `<div class="mini-label">LET’S TRY A REAL-LIFE MOMENT</div><h2>${c.quiz.q}</h2><div class="answer-options">${c.quiz.options.map((o,i)=>`<button data-action="answer" data-answer="${i}" aria-pressed="${selected===i}" class="answer ${selected===i?(correct?'correct':'incorrect'):''}"><span class="answer-letter">${String.fromCharCode(65+i)}</span><span>${o}</span>${selected===i?`<span class="answer-symbol">${correct?'✓':'↻'}</span>`:''}</button>`).join('')}</div>${has?`<div class="feedback ${correct?'good':'try-again'}" role="status"><strong>${correct?'You’ve got it.':'Let’s rethink that.'}</strong> ${correct?c.quiz.feedback:'That choice could leave someone at risk. Look back at the tips above and try again. There is no time limit.'}</div>`:'<p class="quiz-hint">A small practice moment. You can try again.</p>'}`}
function chapterBody(c,path){switch(c.type){
 case 'place':return `<div class="fact-row"><div><span class="fact-icon">${icon('map')}</span><h3>Rain + river</h3><p>Southbank can experience flash flooding from heavy rain and flooding from the Yarra River.</p></div><div><span class="fact-icon">${icon('building')}</span><h3>Think beyond your floor</h3><p>Flooded streets and basements can affect access, lifts, power and shared services.</p></div></div>${floodPhotoLesson()}${mapPanel(true)}${notice('<strong>Your first move:</strong> set a Southbank Watch Zone in the VicEmergency app. Keep another source of information, such as a battery radio, in case your phone fails.')}<div class="white-panel"><h2>Keep these essentials in mind</h2>${list(['<strong>Never walk, ride or drive through floodwater.</strong> Follow current emergency instructions; leave early when advised and safe.','<strong>Choose somewhere you could go early.</strong> Confirm it is outside the affected area, available and suitable for your access and support needs. Relief centres are announced when activated; a nearby park or landmark is not automatically a refuge.','<strong>Move basement valuables before flooding, while it is safe.</strong> Once water enters a garage or basement, stay out and report it.'])}</div>${path==='access'?`<div class="white-panel"><h2>Understand the warning</h2><p><strong>Advice:</strong> stay informed. <strong>Watch and Act:</strong> take action as directed. <strong>Emergency Warning:</strong> you are in danger and need to act immediately.</p><p>Read the full action statement. Warnings can skip levels, and flash flooding can happen without warning. Decide how you will receive and understand updates.</p></div><div class="support-note">You can use larger text or high contrast from <strong>Accessibility</strong> at the top. All activities work with a keyboard, and nothing is timed.</div>`:''}${refs(['local','warnings'])}`;
 case 'kit':return kitHtml(path);
 case 'building':return `<div id="floor-explorer">${floorHtml()}</div>${notice('<strong>Renting?</strong> Ask your property manager who handles building issues and how to report damage. Keep a copy of your lease and photos of your belongings with your plan.')}<p class="body-note">Rats and mice may be displaced after floods. Seal food and report signs to building management; do not enter a flooded space to deal with pests.</p>${refs(['local','health','epa'])}`;
 case 'warnings':return warningsHtml();
 case 'supports':return `<div class="support-grid">${SUPPORT_TOPICS.map(t=>`<button class="support-card ${state.needs.includes(t.id)?'selected':''}" data-action="support" data-topic="${t.id}" aria-pressed="${state.needs.includes(t.id)}">${icon(t.icon)}<span>${t.title}</span><span class="select-mark">${state.needs.includes(t.id)?'✓':'+'}</span></button>`).join('')}</div><div id="support-details">${supportDetails()}</div>${notice('<strong>Carers and neighbours:</strong> ask before helping. Agree how to assist, respect the person’s decisions, and build a backup support network. Do not assume emergency services will already know someone’s needs.')}${refs(['pcep','relay'])}`;
 case 'power':return `<div id="power-explorer">${powerHtml()}</div>${notice('<strong>Before an outage:</strong> if eligible, register life-support needs with your electricity retailer or distributor. Registration does not guarantee continuous power. Agree your medical backup and early relocation plan with your clinician and equipment provider.')}<p class="body-note"><strong>If you are stuck in a lift:</strong> use its emergency alarm/intercom. Do not force doors or try to climb out. If there is immediate danger, call 000.</p>${refs(['power','life','local'])}`;
 case 'access':return accessHtml();
 case 'plan':return `${planForm(path)}<div class="reminders"><h2>Two things to take with you</h2><label class="check-row"><input type="checkbox" data-ack="warning" ${state.ack[path+':warning']?'checked':''}><span>I know to check official warnings and call <strong>000</strong> for immediate danger or <strong>132 500</strong> for flood and storm assistance.</span></label><label class="check-row"><input type="checkbox" data-ack="plan" ${state.ack[path+':plan']?'checked':''}><span>I will confirm my building’s flood procedure${path==='access'?', access and assistance arrangements':''} with the building team and my chosen support people.</span></label></div>`;
 default:return '';
}}
function mapPanel(compact=false){return `<section class="map-panel"><div class="panel-heading"><div><div class="mini-label">SOUTHBANK, MELBOURNE</div><h2>Your local picture</h2></div>${icon('map')}</div><div class="segmented" role="group" aria-label="Map views"><button data-action="map-tab" data-tab="flood" aria-pressed="${mapTab==='flood'}">Flood planning map</button><button data-action="map-tab" data-tab="streets" aria-pressed="${mapTab==='streets'}">Street map</button><button data-action="map-tab" data-tab="safe" aria-pressed="${mapTab==='safe'}">Where can I go?</button></div><div id="map-content">${mapContent(compact)}</div></section>`}
function mapContent(){if(mapTab==='streets')return `<div class="street-placeholder"><span class="icon-box">${icon('map')}</span><h3>Find your bearings</h3><p>Explore local streets using OpenStreetMap. This shows streets and places; it does not show live flood conditions or safe routes.</p><button class="primary" data-action="load-map">Load street map (internet)</button><p class="body-note">The map connects to OpenStreetMap. No personal plan data is sent.</p></div><div class="map-caption"><a href="https://www.openstreetmap.org/#map=16/-37.8234/144.9617" target="_blank" rel="noopener noreferrer">Open a larger street map ↗</a></div>`;
 if(mapTab==='safe')return safePlaces();
 return `<a class="map-clip" href="assets/southbank-flood-guide-2021.pdf#page=2" target="_blank" rel="noopener" aria-label="Open the Southbank flood planning map and full source guide"><img src="assets/southbank-flood-map.png" alt="VICSES Southbank flood awareness map. The Yarra and low-lying areas around City Road, Clarendon Street and Kings Way are shown within potential flood extents. A text explanation follows." width="1132" height="1600"></a><div class="map-caption"><span>VICSES Southbank guide · reviewed 1 July 2021</span><a href="assets/southbank-flood-guide-2021.pdf#page=2" target="_blank" rel="noopener">Open full map ↗</a></div><p class="map-language-note">The original map and PDF are in English. The explanation below is available in your selected language. External services may use their own language settings.</p><details class="map-explainer"><summary>How to read this map · text explanation</summary><p>The blue and purple shading shows potential flood extents in the original guide. City Road, Clarendon Street and Kings Way are identified as susceptible to flooding. Transport and building access may be disrupted.</p><p>A 1% annual chance flood can happen in any year, including consecutive years. Areas outside the shading can still flood. The guide’s “1 in 100-year” label does not mean one flood every 100 years.</p><p>The map is from 2021. It does not show current water, open roads or a guaranteed safe place. Check ${sourceLink('planning','newer Melbourne Water planning information')} and ${sourceLink('warnings','current VicEmergency advice')}.</p></details><div class="map-warning">${icon('shield')}<span>Planning reference only. No live flood overlay or evacuation route is shown.</span></div>`}
function safePlaces(){return `<div class="safe-content"><h3>A suitable destination depends on the flood.</h3><ol class="numbered-list"><li><strong>Plan a place you can reach early.</strong><p>Agree with a friend or family member outside the affected area. Check access, toilets, transport, medication storage and any support you need.</p></li><li><strong>Check official instructions.</strong><p>VicEmergency and the council announce emergency relief arrangements when activated. Confirm a centre is open, suitable and safely reachable before travelling.</p></li><li><strong>Check the building plan.</strong><p>Ask management about exits, a flood assembly location and any designated assistance point. A park, library, lobby or upper floor is not automatically a safe refuge.</p></li></ol><div class="actions">${sourceLink('warnings','Check official warnings & advice')}<button class="text-button" data-action="help">Who can I contact?</button></div><div class="notice warning"><strong>If your route is flooded, do not enter it.</strong> Stay clear of the water and follow emergency instructions. If trapped or in immediate danger, call 000 and give your exact location.</div></div>`}
function mapPage(){return `<div class="page"><a class="back-link" href="${route(state.lastPath)}">← Back to my learning path</a><div class="eyebrow">Local know-how</div><h1>Get to know your neighbourhood.</h1><p class="page-intro">Use the planning map to learn about risk. Use current official advice when you need to act.</p><div class="map-page-grid">${mapPanel()}<aside><div class="white-panel"><h2>Three local reminders</h2>${list(['Southbank can flood from intense rain as well as the Yarra River.','City Road, Clarendon Street and Kings Way are highlighted in the local guide.','No shading, landmark or high floor is a guarantee of safety.'])}${sourceLink('guides','Check for a newer local guide')}</div>${buildingDetails()}<div class="notice"><strong>Maps work differently offline.</strong><p>The included flood guide stays available. Street maps, current warnings and online booking need an internet connection.</p></div></aside></div></div>`}
function kitHtml(path){const count=state.packed[path].filter(id=>KIT_ITEMS.find(i=>i.id===id)?.essential).length;return `<div class="kit-board"><div class="kit-header"><div><div class="mini-label">TAP TO PACK · NO DRAGGING NEEDED</div><h2>Build your emergency kit</h2></div><div class="bag-count"><span id="bag-count">${count}</span><small>of 7 essentials</small></div></div><div class="kit-grid">${KIT_ITEMS.map(item=>`<button class="kit-item ${state.packed[path].includes(item.id)?'packed':''}" aria-pressed="${state.packed[path].includes(item.id)}" data-action="kit" data-item="${item.id}"><span class="kit-item-top">${kitPicture(item.id)}<span class="pack-symbol">${state.packed[path].includes(item.id)?'✓':'+'}</span></span><strong>${item.name}</strong></button>`).join('')}</div><div id="kit-tip" role="status" class="kit-tip">${bagReady(path)?'All seven essentials are in your kit. Keep it manageable and review it regularly.':'Choose an item to see why it matters.'}</div><button class="primary" data-action="check-kit">Check my bag ${icon('check')}</button><div id="kit-result" role="status"></div></div>${notice('<strong>Medicine matters.</strong> Plan your usual medicines before a flood. Keep a written list and prescriptions. Ask your pharmacist or clinician about supply and storage, especially refrigerated medicines. Do not change treatment or doses because of this module.')}${path==='access'?`<div class="white-panel"><h3>Your personal additions</h3>${list(['Chargers, spare batteries and compatible backup equipment agreed with your provider.','A communication card, hearing-aid supplies, glasses or sensory comfort items.','Personal-care supplies and instructions you choose to share.','Food, water, medication and identification for an assistance animal.'])}</div>`:''}${refs(['kit','local','power'])}`}
function bagReady(path){return KIT_ITEMS.every(i=>i.essential===state.packed[path].includes(i.id))}
function floorHtml(){const f=FLOOR_INFO.find(f=>f.id===floorTab)||FLOOR_INFO[0];return `<div class="building-explorer"><div class="floor-buttons" role="group" aria-label="Explore parts of an apartment building">${FLOOR_INFO.map(i=>`<button data-action="floor" data-floor="${i.id}" aria-pressed="${i.id===floorTab}"><span>${i.level}</span><strong>${i.title}</strong></button>`).join('')}</div><div class="floor-detail">${buildingPicture(f.id)}<div class="mini-label">${f.tag}</div><h2>${f.title}</h2><p>${f.body}</p>${list(f.tasks)}</div></div>`}
function supportDetails(){const topics=SUPPORT_TOPICS.filter(t=>state.needs.includes(t.id));return topics.length?topics.map(t=>`<div class="support-detail"><h3>${t.title}</h3><p>${t.body}</p></div>`).join(''):'<p class="body-note">Choose a topic to see ideas for your plan, or continue with the shared guidance below.</p>'}
function powerHtml(){const p=POWER_INFO.find(i=>i.id===powerTab)||POWER_INFO[0];return `<div class="power-panel"><div class="power-title">${icon('battery')}<span>POWER-CUT EXPLORER</span></div><div class="power-tabs" role="group" aria-label="Effects of a power cut">${POWER_INFO.map(i=>`<button data-action="power" data-power="${i.id}" aria-pressed="${i.id===powerTab}">${icon(i.icon)}<span>${i.title}</span></button>`).join('')}</div><div class="power-detail"><div class="power-illustration">${powerPicture(p.id)}</div><h2>${p.title}</h2><p>${p.body}</p></div></div>`}
function warningsHtml(){return `<div class="warning-levels"><div class="warning-level advice"><span class="warning-triangle" aria-hidden="true">!</span><div><h3>Advice</h3><p>Stay informed. Check what is happening and what the message asks you to do.</p></div></div><div class="warning-level watch"><span class="warning-triangle" aria-hidden="true">!</span><div><h3>Watch and Act</h3><p>The threat has increased. Take action now as directed to protect yourself and others.</p></div></div><div class="warning-level emergency"><span class="warning-triangle" aria-hidden="true">!</span><div><h3>Emergency Warning</h3><p>You are in danger. Act immediately on the instructions in the warning.</p></div></div></div><p class="body-note">Warnings can change quickly and may skip levels. Do not wait for a particular colour or a message before responding to danger.</p><div class="white-panel"><h2>Before you head out</h2>${list(['Read the warning’s location and action statement. Set a VicEmergency Watch Zone for home.','Check on your housemates and chosen support person. Take your grab bag and essential medicines.','Follow the advised action. Leave early when advised and safe; never cross floodwater, even if it looks shallow.','Avoid basements, underpasses and riverside shortcuts. Do not use lifts or escalators during flooding.','Leave electrical switchboards and building services to authorised people. Never touch equipment in a wet area.'])}</div>${refs(['warnings','flood','local'])}`}
function accessHtml(){return `<div class="infrastructure-list">${[
 ['Step-free routes','Locate the accessible exit and the backup route. Check thresholds, slopes, door widths and whether powered doors can be opened safely without power.'],
 ['Assistance points','Ask whether the building has a designated refuge or safe waiting location, how it is used, and how your location will be communicated. Do not assume one exists or is safe in a flood.'],
 ['Alerts you can receive','Ask about visual, audible and text alerts. Check whether intercoms and communication systems have backup power and what happens if they fail.'],
 ['Trained help & evacuation','Agree a personal emergency evacuation plan with management and your chosen support people. Confirm who is trained to use any evacuation equipment.'],
 ['A suitable destination','Check accessible transport, toilets, personal care, equipment power and assistance-animal arrangements before you need to relocate.']
 ].map(([title,body],i)=>`<div class="infrastructure-item"><span class="journey-number">${i+1}</span><div><h3>${title}</h3><p>${body}</p></div></div>`).join('')}</div>${buildingDetails()}<div class="white-panel"><h2>Who can help with what?</h2>${list(['<strong>Building manager or emergency warden:</strong> building procedures, verified exits and assistance arrangements. Ask who is available after hours.','<strong>Your chosen carer, trusted person or support coordinator:</strong> a personal plan, backup support and agreed check-ins.','<strong>Clinician, pharmacist and equipment provider:</strong> medication storage, equipment backups and when to relocate.','<strong>Emergency services:</strong> call 000 for immediate danger. Tell them your building, floor, unit or exact location and the assistance you need.'])}<button class="secondary" data-action="help">Accessible emergency contact options ${icon('arrow')}</button></div>${refs(['pcep','relay','power'])}`}
function buildingDetails(){const has=!!config.buildingName;return `<section class="building-details"><div class="mini-label">YOUR BUILDING</div><h2>${has?provided(config.buildingName):'Bring these questions to the walk.'}</h2>${has?`<p>${provided(config.address)}</p>`:''}${!has?'<p>A building has not been added yet. Exits, assistance points and facilities below need to be confirmed by your building team.</p>':''}<dl>${[
 ['Building contact',[config.managerName,config.managerPhone].filter(Boolean).join(' · ')],['Walk meeting point',config.meetingPoint],['Accessible exit / backup route',config.accessibleExit],['Flood & evacuation procedure',config.evacuationPlan],['Access features & power backup',config.infrastructure]
 ].map(([title,value])=>`<div><dt>${title}</dt><dd>${value?provided(value):'<span class="unconfirmed">Confirm with the building team</span>'}</dd></div>`).join('')}</dl>${config.verifiedOn?`<p class="body-note"><span>Details supplied by the organiser · checked</span> ${provided(config.verifiedOn)}. <span>Reconfirm if conditions or arrangements change.</span></p>`:''}<p class="body-note">The walk meeting point is for orientation. It is not automatically a flood evacuation destination.</p></section>`}
function planForm(path){return `<div class="plan-card"><div class="panel-heading"><div><div class="mini-label">YOUR TAKE-AWAY</div><h2>My Southbank plan</h2></div>${icon('document')}</div><p>All fields are optional. Add notes now or download a blank plan to complete privately.</p><p class="privacy-line">${icon('shield')} Notes stay in this page unless you choose to save or download them. Nothing is sent to a building manager.</p><div class="plan-fields">${PLAN_FIELDS.map(f=>`<label class="field" for="plan-${f.key}"><span>${f.label}</span><textarea id="plan-${f.key}" data-plan="${f.key}" maxlength="1500" placeholder="${esc(f.placeholder)}">${esc(state.plan[f.key]||'')}</textarea></label>`).join('')}</div>${path==='access'?notice('<strong>For your supported plan:</strong> agree who helps, how they help, a backup contact, equipment power needs and a safe option if the lift stops. Share personal information only with people you choose.'):''}<label class="check-row"><input type="checkbox" data-action="save-plan" ${state.savePlan?'checked':''}><span>Remember these notes in this browser. Use this only on a device you trust.</span></label><div class="actions"><a class="primary" href="#poster">${icon('download')} Preview my PDF plan</a></div><p class="body-note">You can remove saved progress and notes from “Your data” in the footer.</p></div>`}
function standalonePlan(){return `<div class="page plan-page"><a class="back-link" href="${route(state.lastPath)}">← Back to my learning path</a><div class="eyebrow">Practical things, in one place</div><h1>Your plan. Your next steps.</h1>${planForm(state.lastPath)}${buildingDetails()}</div>`}
function completionPage(path){return `<div class="page completion-page"><div class="completion-badge">${icon('check')}</div><div class="eyebrow">${CHAPTERS[path].length} chapters complete</div><h1>A little more ready.<br><span>Now, meet your neighbours.</span></h1><p class="page-intro">You’ve finished the online learning. Next is a relaxed building walk to turn the ideas into places and people you know.</p>${learningSummary(path)}<div class="completion-grid"><div class="white-panel"><h2>What you’re taking with you</h2>${list(path==='access'?['A personal approach to flood planning.','A plan for access, communication and power interruptions.','Emergency-kit essentials and people to contact.']:['A sense of Southbank’s flood risk.','An emergency kit and safer choices for apartment living.','A plan for warnings, help and checking in.'])}<div class="actions"><a class="secondary" href="#poster">${icon('download')} Preview my PDF plan</a><a class="text-button" href="#plan">Add a note</a></div></div><div class="walk-card"><div class="mini-label">NEXT UP · IN PERSON</div><h2>${path==='access'?'Your supported building orientation':'The new-neighbour building walk'}</h2><p>${path==='access'?'Bring your carer or someone you trust. Plan a pace, route and communication format that work for you.':'Find the exits, meet the building team and get to know a few familiar faces. Bring your housemate, your questions, or just yourself.'}</p><div class="walk-facts"><span>${icon('clock')} ${path==='access'?'About 45':'About 30'} minutes</span><span>${icon('people')} Friendly, small-group format</span></div><a class="primary" href="#book/${path}">Choose my building walk ${icon('arrow')}</a></div></div><p class="body-note">Learning completion is saved on this device. Confirm your actual building arrangements at the walk; this module is not an evacuation certification.</p><a class="back-link" href="#paths">← Explore the other path</a></div>`}
function lockedBooking(path){return `<div class="page narrow-page"><div class="white-panel"><h1>A little learning first.</h1><p>Finish your learning path before choosing your building walk. You can take breaks and return whenever you like.</p><a class="primary" href="${route(path)}">Continue my path ${icon('arrow')}</a></div></div>`}
function demoSlots(){const p=Object.fromEntries(new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Melbourne',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date()).map(p=>[p.type,p.value]));const today=Date.UTC(+p.year,+p.month-1,+p.day);return [2,4,7].map((offset,i)=>{const d=new Date(today+offset*86400000),date=d.toISOString().slice(0,10);return {id:date+'-'+i,date,time:['17:30','11:00','14:00'][i],label:new Intl.DateTimeFormat('en-AU',{weekday:'short',day:'numeric',month:'short',timeZone:'UTC'}).format(d)}})}
function bookingPage(path){
 const url=path==='access'?(config.accessibleBookingUrl||config.bookingUrl):config.bookingUrl;
 const booking=state.booking?.path===path?state.booking:null;
 if(booking)return bookingResult(booking);
 return `<div class="page booking-page"><a class="back-link" href="#complete/${path}">← My learning summary</a><div class="eyebrow">The next step is a familiar face</div><h1>Let’s meet downstairs.</h1><p class="page-intro">A relaxed look around your building. Get your bearings, ask questions, and say hello to your new neighbours.</p><div class="booking-grid"><section class="booking-form white-panel"><h2>${url?'Book with your organiser':'Try the booking flow'}</h2>${url?`<p>Your organiser’s booking page has current sessions and availability. Complete your reservation there to receive confirmation.</p><a class="primary" href="${esc(url)}" target="_blank" rel="noopener noreferrer">Open online booking ${icon('arrow')}</a><p class="body-note"><span>Opens</span> ${provided(new URL(url).hostname)}. <span>Your plan and notes are not sent. This module cannot confirm whether an external booking is completed.</span></p>${path==='access'&&!config.accessibleBookingUrl?notice('Tell the organiser what access or communication arrangements you would like. The link is the general booking page.'):''}`:`<div class="practice-label">PRACTICE BOOKING · NO REAL RESERVATION</div><p>No building sessions have been connected yet. These are sample times to explore how booking will work.</p><form id="booking-form"><fieldset><legend>1. Choose your walk</legend><div class="format-options"><label class="format-choice"><input type="radio" name="format" value="social" ${(!bookingFormat&&path==='resident')||bookingFormat==='social'?'checked':''}><span><strong>New-neighbour walk</strong><small>About 30 min · shared building essentials</small></span></label><label class="format-choice"><input type="radio" name="format" value="supported" ${(!bookingFormat&&path==='access')||bookingFormat==='supported'?'checked':''}><span><strong>Supported orientation</strong><small>About 45 min · plan access and bring a carer</small></span></label></div></fieldset><fieldset><legend>2. Pick a sample time</legend><p class="body-note">All sample times are Melbourne time (Australia/Melbourne).</p><div class="slot-grid">${demoSlots().map(s=>`<label class="slot"><input type="radio" name="slot" value="${s.id}" ${bookingSelection===s.id?'checked':''} required><span><strong data-local-date="${s.date}" translate="no">${I18N.date(s.date)}</strong><span dir="ltr">${s.time}</span><small>Sample session</small></span></label>`).join('')}</div></fieldset><label class="field"><span>What would make the walk work for you? <small>(optional)</small></span><select name="preference"><option value="none">No preference for this practice</option value="carer">Bringing a carer or support person</option><option value="stepfree">Discuss a step-free route</option><option value="quiet">A quieter pace or smaller group</option><option value="communication">Discuss communication access</option><option value="private">Discuss preferences privately with the organiser</option></select></label><p class="body-note">You don’t need to enter a name, email or health details for a practice booking.</p><label class="check-row"><input type="checkbox" name="practice" required><span>I understand this saves a practice selection on this device. It does not contact an organiser or reserve a place.</span></label><button class="primary" type="submit">Save practice selection ${icon('arrow')}</button><div id="booking-error" role="alert"></div></form>`}</section><aside><div class="walk-agenda"><div class="mini-label">YOUR WALK, AT A GLANCE</div><h2>Good to know where.<br>Nice to know who.</h2>${[['01','Say hello','Meet the organiser and a few neighbours. Introductions are optional.'],['02','Take a look around','Locate exits, information points and where to ask for assistance.'],['03','Talk through a “what if”','Find out what your building does if floodwater arrives or the power goes out.'],['04','Leave with a plan','Check your questions and agree any follow-up with the building team.']].map(([n,t,d])=>`<div class="agenda-item"><span>${n}</span><div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}<p class="body-note">This is a proposed session format. Your organiser confirms the location, availability, accessibility and arrangements.</p></div>${buildingDetails()}</aside></div></div>`;
}
function bookingResult(b){const d=new Date(b.date+'T12:00:00Z'),valid=!Number.isNaN(d.getTime()),label=valid?new Intl.DateTimeFormat('en-AU',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(d):'Sample date';return `<div class="page narrow-page"><a class="back-link" href="#complete/${b.path}">← My learning summary</a><div class="white-panel booking-receipt"><div class="completion-badge">${icon('check')}</div><div class="practice-label">PRACTICE ONLY</div><h1>Your practice selection is saved.</h1><p><strong>A real session has not been booked.</strong> Nothing has been sent to a building organiser.</p><dl class="receipt-details"><div><dt>Sample walk</dt><dd>${b.format==='supported'?'Supported orientation':'New-neighbour walk'}</dd></div><div><dt>Sample time</dt><dd><span data-local-date="${b.date}" data-date-style="long" translate="no">${esc(I18N.date(b.date,true))}</span> · <bdi dir="ltr">${esc(b.time)}</bdi><small>Melbourne time</small></dd></div><div><dt>Meeting point</dt><dd>${config.meetingPoint?provided(config.meetingPoint):'To be confirmed by the organiser'}</dd></div><div><dt>Next step</dt><dd>Ask your organiser for the live booking link.</dd></div></dl><div class="actions"><button class="primary" data-action="calendar">Download practice calendar file</button><button class="secondary" data-action="change-booking">Change selection</button></div><p class="body-note">The calendar event is explicitly labelled “PRACTICE ONLY” and tentative.</p><a class="text-button" href="#plan">Take my plan to the walk →</a></div></div>`}
function sourcesPage(){return `<div class="page sources-page"><a class="back-link" href="#welcome">← Back to the module</a><div class="eyebrow">Behind the guidance</div><h1>Good information matters.</h1><p class="page-intro">This independent learning module draws on official Victorian advice and person-centred preparedness resources. It is not an official VICSES product.</p>${notice('<strong>Content checked: 15 September 2026.</strong> The included local flood map was reviewed in July 2021. Use it for learning; check current official warnings for decisions during an event.')}<div class="source-list">${SOURCES.map(s=>`<article><h2>${sourceLink(s.id)}</h2><p>${esc(s.note)}</p></article>`).join('')}</div><div class="white-panel"><h2>Before using this with residents</h2><p>The building organiser needs to verify exits, meeting and assistance points, support arrangements, and power-backup coverage. Add a live booking link in Facilitator setup. Co-review the supported pathway with people with disability and carers from the building.</p><p>No building, refuge, accessible route, session availability, or live flood status is invented by the module.</p></div>${photoCredits()}</div>`}
function openModal(title,body){document.getElementById('modal-body').innerHTML=`<h2 id="modal-title" class="modal-title">${title}</h2>${body}`;I18N.localize(document.getElementById('modal'));document.getElementById('modal').showModal()}
function closeModal(){document.getElementById('modal').close()}
function helpModal(){openModal('The right help, when you need it.',`<p>For immediate danger, contact emergency services. This learning module does not monitor conditions or send alerts.</p><div class="contact-list"><a class="contact urgent" href="tel:000"><span><strong>Life-threatening emergency</strong><small>Police, fire or ambulance</small></span><b>000</b></a><a class="contact" href="tel:132500"><span><strong>VICSES flood & storm assistance</strong><small>Emergency help with flood or storm damage</small></span><b>132 500</b></a><a class="contact" href="tel:1800226226"><span><strong>VicEmergency information</strong><small>Warnings and emergency information</small></span><b>1800 226 226</b></a></div><h3>Accessible emergency calls</h3><p>For NRS users: <strong>106 is a TTY emergency service, not an SMS number.</strong> Use NRS Chat or SMS Relay according to the official instructions. You cannot text 000 directly.</p>${sourceLink('relay','See accessible emergency calling instructions')}<h3 class="space-top">Your building & support network</h3><p>${config.managerName||config.managerPhone?provided([config.managerName,config.managerPhone].filter(Boolean).join(' · ')):'Ask the building manager for the emergency contact and after-hours number. Add it to your personal plan.'}</p><p>Agree backup help with your chosen carer, trusted person or support coordinator. If a power failure puts life-support equipment at risk, follow your medical backup plan and call 000 if life is threatened.</p>${sourceLink('warnings','Open current official warnings')}`)}
function accessibilityModal(){openModal('Make this comfortable.',`<p>Use either pathway with these settings. There are no timers, flashing effects or sound-only instructions.</p><label class="check-row setting-row"><input type="checkbox" data-pref="large" ${state.large?'checked':''}><span><strong>Larger text</strong><small>Increase the base text size throughout the module.</small></span></label><label class="check-row setting-row"><input type="checkbox" data-pref="contrast" ${state.contrast?'checked':''}><span><strong>Higher contrast</strong><small>Darker text and stronger boundaries.</small></span></label><div class="notice"><strong>Keyboard tips</strong><p>Use Tab to move, Enter or Space to choose, and Escape to close this window. Your browser’s zoom also works.</p></div><p>Motion follows your device’s reduced-motion setting. All content is text-based and can be used with browser or screen-reader read-aloud tools.</p>`)}
function privacyModal(){openModal('Your notes belong to you.',`<p>Progress, personal plan notes, support choices and practice bookings stay in this browser. Plan notes are only saved after closing if you choose “Remember these notes”.</p><p>With your permission, anonymous quiz answers, retries, scores and timestamps are saved on the organiser’s server. No names, contact details or plan notes are sent.</p>${trackingPrivacy()}<p>External maps and booking links use their own privacy policies. No plan notes are attached to those links.</p><p>Clearing this device does not delete results already shared. Delete shared results first if you want to remove them from the server.</p><div class="actions"><button class="secondary" data-action="clear-confirm">Clear my saved learning data</button></div>`)}
function setupModal(){openModal('Connect your building.',`<p>Add details verified by your building team and a real booking page. These settings are for the organiser and are visible to learners.</p><form id="setup-form">${[
 ['buildingName','Building name'],['address','Building address'],['managerName','Building / emergency contact'],['managerPhone','Contact phone and after-hours details'],['meetingPoint','Orientation meeting point (not a flood refuge)'],['accessibleExit','Verified accessible exit and backup route'],['evacuationPlan','Building flood procedure / assistance instructions'],['infrastructure','Verified access features and backup-power coverage'],['verifiedOn','Date details were checked'],['bookingUrl','Resident booking link (HTTPS)'],['accessibleBookingUrl','Supported orientation booking link (HTTPS, optional)']
 ].map(([key,label])=>`<label class="field"><span>${label}</span>${['evacuationPlan','infrastructure','accessibleExit'].includes(key)?`<textarea name="${key}" maxlength="2500">${esc(config[key])}</textarea>`:`<input name="${key}" type="${key.includes('Url')?'url':key==='verifiedOn'?'date':'text'}" value="${esc(config[key])}" maxlength="2500" ${key.includes('Url')?'placeholder="https://…"':''}>`}</label>`).join('')}<div class="notice">The live link replaces the practice booking form. Actual reservations and confirmation are handled by your booking provider.</div><div id="setup-error" role="alert"></div><button class="primary" type="submit">Save settings on this device</button><button class="secondary" type="button" data-action="export-config">Download config.js</button><p class="body-note">To share these settings with all learners: download config.js, replace the file in the website folder, then share that folder. Browser-only settings affect this device.</p></form>`)}
function configFromForm(){const form=document.getElementById('setup-form');const raw=form?Object.fromEntries(new FormData(form)):config;for(const key of ['bookingUrl','accessibleBookingUrl']){if(raw[key]&&!validUrl(raw[key]))throw new Error('Please use a complete HTTPS booking link.')}return cleanConfig(raw)}
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function planText(){
 const t=I18N.t;
 const fieldLabels={buildingName:'Building name',address:'Building address',managerName:'Building / emergency contact',managerPhone:'Contact phone and after-hours details',meetingPoint:'Orientation meeting point (not a flood refuge)',accessibleExit:'Verified accessible exit and backup route',evacuationPlan:'Building flood procedure / assistance instructions',infrastructure:'Verified access features and backup-power coverage',verifiedOn:'Date details were checked'};
 const reminders=['Never enter floodwater or a flooding basement to retrieve property.','Follow current official warnings. Leave early when advised and safe.','Confirm building exits and personal assistance arrangements in advance.','Do not rely on lifts during flooding or a power cut.','Prepare compatible backup power and a relocation plan with your providers.','A planning map or orientation meeting point is not a guarantee of a safe refuge.'];
 return [t('SOUTHBANK READY — MY PERSONAL PLAN'),t('Prepared: {date}',{date:new Date().toLocaleDateString(I18N.locale)}),'',...PLAN_FIELDS.flatMap(f=>[t(f.label),state.plan[f.key]||t('To discuss / complete'),'']),t('EMERGENCY CONTACTS'),t('Life-threatening emergency')+': 000',t('VICSES flood & storm assistance')+': 132 500',t('VicEmergency information')+': 1800 226 226',t('Current warnings')+': https://www.emergency.vic.gov.au/',t('Accessible emergency calls')+': https://www.accesshub.gov.au/about-the-nrs/how-to-make-an-emergency-call-using-the-nrs',t('106 is for TTY emergency calls, not SMS.'),'',t('MY KIT CHECKLIST'),...KIT_ITEMS.filter(i=>i.essential).map(i=>'[ ] '+t(i.name)+' — '+t(i.detail)),'[ ] '+t('Personal support supplies, equipment backups and assistance-animal essentials if needed.'),'',t('KEY REMINDERS'),...reminders.map(r=>t(r)),'',t('BUILDING INFORMATION'),...Object.entries(fieldLabels).map(([k,label])=>t(label)+': '+(config[k]||t('Not configured'))),'',t('This is a personal preparation worksheet, not a live warning or evacuation certification. Keep it private and up to date.'),''].join('\n');
}

function calendarText(b){
 // Resolve Melbourne wall time to UTC so calendar clients need no timezone table.
 const [year,month,day]=b.date.split('-').map(Number),[hour,minute]=b.time.split(':').map(Number),wall=Date.UTC(year,month-1,day,hour,minute);
 let utc=wall;
 for(let i=0;i<3;i++){const p=Object.fromEntries(new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Melbourne',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(utc)).map(v=>[v.type,v.value]));utc+=wall-Date.UTC(+p.year,+p.month-1,+p.day,+p.hour,+p.minute)}
 const stamp=value=>new Date(value).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
 const ics=value=>value.replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');
 const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Southbank Ready//Practice orientation//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+b.id+'@southbank-ready.local','DTSTAMP:'+stamp(Date.now()),'DTSTART:'+stamp(utc),'DTEND:'+stamp(utc+(b.format==='supported'?45:30)*60000),'SUMMARY:'+ics(I18N.t('PRACTICE ONLY - Southbank building walk')),'DESCRIPTION:'+ics(I18N.t('No real reservation. No organiser has been contacted. Ask for the live booking link.')),'LOCATION:'+ics(I18N.t('To be confirmed - demonstration only')),'STATUS:TENTATIVE','END:VEVENT','END:VCALENDAR'];
 // RFC 5545 folds by UTF-8 octets, without splitting Arabic or Chinese characters.
 const encoder=new TextEncoder();
 return lines.map(line=>{let out='',column=0;for(const ch of line){const bytes=encoder.encode(ch).length;if(column+bytes>75){out+='\r\n ';column=1}out+=ch;column+=bytes}return out}).join('\r\n')+'\r\n';
}
document.addEventListener('click',event=>{
 if(event.target.closest('.skip-link')){event.preventDefault();main.focus();main.scrollIntoView();return}
 const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
 if(action==='restart-path')restartPath(target.dataset.path);
 else if(action==='help')helpModal();
 else if(action==='accessibility')accessibilityModal();
 else if(action==='privacy')privacyModal();
 else if(action==='setup')setupModal();
 else if(action==='close-modal')closeModal();
 else if(action==='answer'){
  const c=CHAPTERS[current.path][current.index],answer=Number(target.dataset.answer);if(!c.quiz||!Number.isInteger(answer)||answer<0||answer>=c.quiz.options.length)return;
  Learning.practice(current.path,c.id,[String(answer)]);state.answers[current.path+':'+c.id]=answer;save();document.getElementById('quiz-content').innerHTML=quizHtml(c,current.path);I18N.localize(document.getElementById('quiz-content'));document.querySelector(`[data-answer="${answer}"]`).focus({preventScroll:true});updateContinue();announce(answer===c.quiz.correct?I18N.t('You’ve got it.')+' '+I18N.t(c.quiz.feedback):'Try again. Look back at the tips above.');
 }
 else if(action==='continue'){
  const c=CHAPTERS[current.path][current.index];if(!ready(c,current.path))return;
  if(!state.completed[current.path].includes(current.index))state.completed[current.path].push(current.index);save();
  const next=current.index+1;location.hash=next<CHAPTERS[current.path].length?route(current.path,next):route(current.path);
 }
 else if(action==='map-tab'){mapTab=target.dataset.tab;document.querySelectorAll('[data-action="map-tab"]').forEach(b=>b.setAttribute('aria-pressed',b===target));document.getElementById('map-content').innerHTML=mapContent();announce(I18N.t('Showing {view}',{view:target.textContent}))}
 else if(action==='load-map'){
  document.querySelector('.street-placeholder').outerHTML='<iframe class="street-map" title="OpenStreetMap streets of Southbank — not flood routes" loading="eager" referrerpolicy="no-referrer" src="https://www.openstreetmap.org/export/embed.html?bbox=144.945%2C-37.833%2C144.973%2C-37.814&amp;layer=mapnik"></iframe><p class="body-note">If the map does not load, use “Open a larger street map” below. Streets are shown for orientation only.</p>';
 }
 else if(action==='kit'){
  const item=KIT_ITEMS.find(i=>i.id===target.dataset.item);if(!item)return;const packed=state.packed[current.path],index=packed.indexOf(item.id);index>=0?packed.splice(index,1):packed.push(item.id);save();target.classList.toggle('packed',index<0);target.setAttribute('aria-pressed',index<0);target.querySelector('.pack-symbol').textContent=index<0?'✓':'+';document.getElementById('bag-count').textContent=packed.filter(id=>KIT_ITEMS.find(i=>i.id===id)?.essential).length;document.getElementById('kit-tip').textContent=item.detail;document.getElementById('kit-result').innerHTML='';updateContinue();announce(I18N.t(item.name)+'. '+I18N.t(item.detail));
 }
 else if(action==='check-kit'){
  Learning.practice(current.path,'kit',state.packed[current.path]);
  const packed=state.packed[current.path],missing=KIT_ITEMS.filter(i=>i.essential&&!packed.includes(i.id)),unsafe=KIT_ITEMS.filter(i=>!i.essential&&packed.includes(i.id));const text=bagReady(current.path)?'<strong>Your core kit is ready.</strong> Add your personal essentials, check expiry dates and keep it within reach.':`${missing.length?'<strong>Add these essentials:</strong> '+missing.map(i=>'<span>'+i.name+'</span>').join(', ')+'. ':''}${unsafe.length?'<strong>Take these out:</strong> '+unsafe.map(i=>'<span>'+i.name+'</span>').join(', ')+'.':''}`;document.getElementById('kit-result').innerHTML=notice(text,bagReady(current.path)?'success':'warning');I18N.localize(document.getElementById('kit-result'));announce(document.getElementById('kit-result').textContent);updateContinue();
 }
 else if(action==='floor'){floorTab=target.dataset.floor;document.getElementById('floor-explorer').innerHTML=floorHtml();document.querySelector(`[data-floor="${floorTab}"]`).focus({preventScroll:true});announce(FLOOR_INFO.find(i=>i.id===floorTab).title)}
 else if(action==='power'){powerTab=target.dataset.power;document.getElementById('power-explorer').innerHTML=powerHtml();document.querySelector(`[data-power="${powerTab}"]`).focus({preventScroll:true});announce(POWER_INFO.find(i=>i.id===powerTab).title)}
 else if(action==='support'){const id=target.dataset.topic,index=state.needs.indexOf(id);index>=0?state.needs.splice(index,1):state.needs.push(id);save();target.classList.toggle('selected',index<0);target.setAttribute('aria-pressed',index<0);target.querySelector('.select-mark').textContent=index<0?'✓':'+';document.getElementById('support-details').innerHTML=supportDetails();announce(I18N.t(index<0?'Selected: {topic}':'Removed: {topic}',{topic:I18N.t(SUPPORT_TOPICS.find(t=>t.id===id).title)}))}
 else if(action==='print-plan')printPlan();
 else if(action==='export-config'){try{const value=configFromForm();download('config.js','// Building settings supplied by your organiser. No secrets.\nwindow.SOUTHBANK_CONFIG = '+JSON.stringify(value,null,2)+';\n','text/javascript');announce('Building settings downloaded.')}catch(error){document.getElementById('setup-error').textContent=error.message}}
 else if(action==='calendar'&&state.booking){download('PRACTICE-Southbank-walk.ics',calendarText(state.booking),'text/calendar;charset=utf-8')}
 else if(action==='change-booking'){state.booking=null;save();render()}
 else if(action==='clear-confirm'){document.getElementById('modal-body').innerHTML='<h2 id="modal-title">Clear learning data on this device?</h2><p>This removes saved progress, kit choices, personal notes and the practice booking. Save your PDF first if you want to keep it. Shared quiz results stay on the server unless you delete them first in “Your data”. Building settings are kept.</p><div class="actions"><button class="secondary" data-action="close-modal">Keep my data</button><button class="primary" data-action="clear-data">Clear my learning data</button></div>'}
 else if(action==='clear-data'){Learning.clearLocal();try{localStorage.removeItem(STORE)}catch{}state={lastPath:'resident',completed:{resident:[],access:[]},answers:{},packed:{resident:[],access:[]},needs:[],ack:{},plan:{},savePlan:false,large:false,contrast:false,booking:null};closeModal();save();location.hash='#welcome';render();announce('Your learning data has been cleared.')}
 I18N.localize();
});
document.addEventListener('input',event=>{const target=event.target;if(target.dataset.plan&&PLAN_FIELDS.some(f=>f.key===target.dataset.plan)){state.plan[target.dataset.plan]=target.value.slice(0,1500);save()}});
document.addEventListener('change',event=>{
 const t=event.target;
 if(t.id==='language-select'){I18N.setLanguage(t.value);return}
 if(t.dataset.pref){state[t.dataset.pref]=t.checked;preferences();save()}
 if(t.dataset.ack){state.ack[current.path+':'+t.dataset.ack]=t.checked;save();updateContinue()}
 if(t.dataset.action==='save-plan'){state.savePlan=t.checked;save();announce(t.checked?'Plan notes will be saved in this browser.':'Plan notes are only kept in this page; the saved copy has been removed.')}
 if(t.name==='slot')bookingSelection=t.value;
 if(t.name==='format')bookingFormat=t.value;
 I18N.localize();
});
document.addEventListener('submit',event=>{
 if(event.target.id==='setup-form'){event.preventDefault();try{config=configFromForm();localStorage.setItem('southbank-building',JSON.stringify(config));closeModal();state.booking=null;save();render(false);announce('Building settings saved on this device.')}catch(error){document.getElementById('setup-error').textContent=error.message||'Settings could not be saved. Use Download config.js instead.'}}
 if(event.target.id==='booking-form'){event.preventDefault();if(!readyToBook(current.path))return;const data=new FormData(event.target),slot=demoSlots().find(s=>s.id===data.get('slot'));if(!slot||!data.get('practice')){document.getElementById('booking-error').textContent='Choose a sample time and acknowledge that this is a practice booking.';return}state.booking={id:'practice-'+Date.now(),path:current.path,date:slot.date,time:slot.time,format:data.get('format')==='supported'?'supported':'social',preference:String(data.get('preference')||'none'),status:'practice-only'};save();render();announce('Practice selection saved. No real session has been booked.')}
 I18N.localize();
});
document.getElementById('modal').addEventListener('click',event=>{if(event.target.id==='modal'){const box=event.target.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)closeModal()}});
window.addEventListener('hashchange',()=>render());
preferences();render(false);
void Learning.connect().then(()=>{if(current.view==='paths')render(false)});
// Feature-detected agent tools share the exact state and navigation used by the UI.
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});for(const tool of [
 {name:'get_learning_progress',title:'Read learning progress',description:'Read the current path and device-local chapter progress. Does not expose personal plan notes.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>{if(!isObject(input)||Object.keys(input).length)throw new Error('Expected an empty object.');return {path:state.lastPath,resident:{completed:state.completed.resident.length,total:5},access:{completed:state.completed.access.length,total:6}}}},
 {name:'start_learning_path',title:'Open a learning path',description:'Navigate to the next unfinished chapter of the chosen path. This does not mark chapters complete or create a booking.',inputSchema:{type:'object',properties:{path:{type:'string',enum:['resident','access']}},required:['path'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!isObject(input)||Object.keys(input).length!==1||!['resident','access'].includes(input.path))throw new Error('Choose resident or access.');state.lastPath=input.path;save();location.hash=route(input.path);render();return {path:input.path,chapter:resumeIndex(input.path),learningComplete:complete(input.path)}}}
]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}}
